AESTestAnnouncementExtension.prototype = (Object.extendsObject(x_733168_aes.AESAnnouncementExtension, {
    initialize: function() {},

    transformAnnouncement: function(announcement, gr, options) {

        announcement.custom_field = "WORKED";

        return announcement;
    },

    type: 'AESTestAnnouncementExtension'
}));
